#include <Arduino.h>

// ==================== Конфигурация пинов ====================
#define SENSOR1_PIN A0    // ЭМГ-датчик 1
#define SENSOR2_PIN A1    // ЭМГ-датчик 2
#define BUTTON_PIN  2     // Многофункциональная кнопка (с подтяжкой к GND)
#define LED_PIN     13    // Встроенный светодиод

// ==================== Параметры ====================
#define SENSOR_THRESHOLD 500   // Порог срабатывания датчика (0-1023)
#define NUM_FINGERS 5          // Количество пальцев (I..V)
#define ANGLE_MIN 0            // Полностью разжато
#define ANGLE_MAX 100          // Полностью сжато
#define INIT_DELAY 500         // Задержка при инициализации каждого пальца (мс)
#define PAUSE_DURATION 5000    // Пауза 5 секунд
#define BUTTON_DEBOUNCE 50     // Антидребезг (мс)
#define SHORT_PRESS_MIN 300    // Минимальная длительность короткого нажатия (мс)
#define SHORT_PRESS_MAX 500    // Максимальная длительность короткого нажатия (мс)
#define LONG_PRESS_MIN 3000    // Длительность для аварийного режима (мс)
#define DOUBLE_CLICK_INTERVAL 500 // Максимальный интервал между двумя нажатиями (мс)
#define LED_FLASH_PERIOD 1000  // Период мигания светодиода (мс) для ONE_SENSOR и EMERGENCY
#define LED_TWO_SHORT_ON 100   // Длительность первой короткой вспышки (мс)
#define LED_TWO_SHORT_OFF 100  // Пауза между вспышками (мс)

// ==================== Типы данных ====================
enum SystemState {
    STATE_INIT,
    STATE_PAUSE,
    STATE_ONE_SENSOR,
    STATE_MODE1,
    STATE_MODE2,
    STATE_EMERGENCY
};

// Схваты (для режимов с двумя датчиками)
enum GripType {
    GRIP_POWER,           // Силовой схват
    GRIP_CLOSED_PINCER,   // Закрытый пинцетный
    GRIP_OPEN_PINCER,     // Открытый пинцетный
    GRIP_KEYBOARD,        // Работа с клавиатурой
    GRIP_CUP_HOLD         // Удержание стакана
};

// Структура для описания схвата
struct GripDefinition {
    GripType type;
    uint8_t targetAngles[NUM_FINGERS]; // Целевые углы для каждого пальца (0-100)
    bool hold;                // С удержанием?
    uint8_t speed;            // Скорость движения (%)
};

// ==================== Глобальные переменные ====================
SystemState currentState = STATE_INIT;
SystemState prevState = STATE_INIT; // для отслеживания смены режима

// Текущие и целевые углы пальцев (0-100)
volatile int currentAngles[NUM_FINGERS] = {0,0,0,0,0};
volatile int targetAngles[NUM_FINGERS] = {0,0,0,0,0};
uint8_t currentSpeed = 100; // текущая скорость (по умолчанию)

// Флаги для обработки кнопки
volatile bool buttonPressed = false;
volatile unsigned long buttonPressTime = 0;
volatile unsigned long buttonReleaseTime = 0;
volatile bool buttonLongPressHandled = false;
volatile bool buttonShortPressHandled = false;

// Для определения двойного клика
volatile unsigned long lastSingleClickTime = 0;
volatile bool singleClickPending = false;
volatile bool doubleClickDetected = false;

// Для управления светодиодом
unsigned long lastLEDToggleTime = 0;
bool ledState = false;
int ledFlashMode = 0; // 0 - выключен, 1 - горит, 2 - мигание 1Гц, 3 - два коротких мигания

// Для управления схватами
GripType currentGrip = GRIP_POWER;
bool gripActive = false;          // Выполняется ли в данный момент схват (удержание)
bool gripHoldActive = false;      // Активно ли удержание для текущего схвата
uint8_t gripSpeed = 100;

// Для комбинаций датчиков в режиме двух датчиков
bool sensor1Active = false;
bool sensor2Active = false;
bool prevSensor1Active = false;
bool prevSensor2Active = false;

// Таймеры
unsigned long initStartTime = 0;
unsigned long pauseStartTime = 0;
unsigned long emergencyStartTime = 0;
bool emergencyExitPending = false;

// Состояние инициализации пальцев
int initFingerIndex = 0;
bool initPhase = 0; // 0 - сгибание, 1 - разгибание

// ==================== Прототипы функций ====================
void setFinger(int finger, int angle, int speed);
void updateFingers();
void executeGrip(GripType grip, bool hold, uint8_t speed);
void releaseGrip();
void updateLED();
void handleButton();
void processSensors();
void initSystem();
void moveFingerGradually(int finger, int target, int speed);
bool isSensorActive(int pin);

// Определения схватов (таблица из ТЗ)
const GripDefinition grips[] = {
    // GRIP_POWER
    {GRIP_POWER, {100,100,100,100,100}, true, 90}, // для MODE1 скорость 90%, для MODE2 70% (задаётся отдельно)
    // GRIP_CLOSED_PINCER
    {GRIP_CLOSED_PINCER, {100,100,100,100,100}, false, 70}, // I,II,III сжимаются, IV,V сжаты постоянно
    // GRIP_OPEN_PINCER
    {GRIP_OPEN_PINCER, {100,100,0,0,0}, true, 70}, // I,II сжимаются, остальные разжаты
    // GRIP_KEYBOARD
    {GRIP_KEYBOARD, {100,0,100,100,100}, true, 70}, // II разжат, остальные сжаты
    // GRIP_CUP_HOLD
    {GRIP_CUP_HOLD, {100,100,100,100,100}, true, 50} // V сжат, I-IV схват/раскрытие
};

// ==================== Реализация функций ====================

void setup() {
    Serial.begin(115200);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(LED_PIN, OUTPUT);
    pinMode(SENSOR1_PIN, INPUT);
    pinMode(SENSOR2_PIN, INPUT);

    // Начальное состояние
    currentState = STATE_INIT;
    initStartTime = millis();
    initFingerIndex = 0;
    initPhase = 0;

    // Устанавливаем все пальцы в 0
    for (int i = 0; i < NUM_FINGERS; i++) {
        currentAngles[i] = 0;
        targetAngles[i] = 0;
    }

    Serial.println("Система запущена. Инициализация...");
}

void loop() {
    // Обновление состояния пальцев (плавное движение)
    updateFingers();

    // Обработка кнопки
    handleButton();

    // Обработка датчиков и состояния
    switch (currentState) {
        case STATE_INIT:
            initSystem();
            break;
        case STATE_PAUSE:
            if (millis() - pauseStartTime >= PAUSE_DURATION) {
                currentState = STATE_ONE_SENSOR;
                ledFlashMode = 2; // Два коротких мигания
                lastLEDToggleTime = millis();
                Serial.println("Переход в режим ONE_SENSOR");
            }
            break;
        case STATE_ONE_SENSOR:
            processOneSensor();
            break;
        case STATE_MODE1:
            processTwoSensors(MODE1);
            break;
        case STATE_MODE2:
            processTwoSensors(MODE2);
            break;
        case STATE_EMERGENCY:
            processEmergency();
            break;
    }

    // Обновление светодиода
    updateLED();

    // Небольшая задержка для стабильности
    delay(10);
}

// ==================== Инициализация системы ====================
void initSystem() {
    static bool initDone = false;
    if (!initDone) {
        // Последовательная проверка каждого пальца
        if (initFingerIndex < NUM_FINGERS) {
            if (initPhase == 0) {
                // Сгибаем палец до упора
                setFinger(initFingerIndex, ANGLE_MAX, 50);
                delay(INIT_DELAY);
                initPhase = 1;
            } else {
                // Разгибаем палец
                setFinger(initFingerIndex, ANGLE_MIN, 50);
                delay(INIT_DELAY);
                initFingerIndex++;
                initPhase = 0;
            }
        } else {
            // Инициализация завершена
            initDone = true;
            currentState = STATE_PAUSE;
            pauseStartTime = millis();
            Serial.println("Инициализация завершена. Пауза 5 сек...");
        }
    }
}

// ==================== Управление пальцами ====================
void setFinger(int finger, int angle, int speed) {
    if (finger < 0 || finger >= NUM_FINGERS) return;
    targetAngles[finger] = constrain(angle, ANGLE_MIN, ANGLE_MAX);
    currentSpeed = speed;
    // В реальном проекте здесь был бы код управления сервоприводом или двигателем
}

void updateFingers() {
    for (int i = 0; i < NUM_FINGERS; i++) {
        if (currentAngles[i] != targetAngles[i]) {
            // Плавное перемещение с заданной скоростью
            int diff = targetAngles[i] - currentAngles[i];
            int step = (diff > 0) ? max(1, (currentSpeed * diff) / 100) : min(-1, (currentSpeed * diff) / 100);
            currentAngles[i] += step;
            // Проверка на перелёт
            if ((diff > 0 && currentAngles[i] > targetAngles[i]) || (diff < 0 && currentAngles[i] < targetAngles[i])) {
                currentAngles[i] = targetAngles[i];
            }
        }
    }
}

// ==================== Схваты ====================
void executeGrip(GripType grip, bool hold, uint8_t speed) {
    const GripDefinition* def = nullptr;
    // Выбор определения в зависимости от типа
    switch (grip) {
        case GRIP_POWER: def = &grips[0]; break;
        case GRIP_CLOSED_PINCER: def = &grips[1]; break;
        case GRIP_OPEN_PINCER: def = &grips[2]; break;
        case GRIP_KEYBOARD: def = &grips[3]; break;
        case GRIP_CUP_HOLD: def = &grips[4]; break;
    }
    if (!def) return;

    // Устанавливаем целевые углы для всех пальцев
    for (int i = 0; i < NUM_FINGERS; i++) {
        setFinger(i, def->targetAngles[i], speed);
    }
    currentGrip = grip;
    gripHoldActive = hold;
    gripActive = true;
    Serial.print("Выполняется схват: ");
    Serial.println(grip);
}

void releaseGrip() {
    // Возвращаем все пальцы в исходное положение (разжато)
    for (int i = 0; i < NUM_FINGERS; i++) {
        setFinger(i, ANGLE_MIN, 100);
    }
    gripActive = false;
    gripHoldActive = false;
    Serial.println("Схват отпущен");
}

// ==================== Обработка режима ONE_SENSOR ====================
void processOneSensor() {
    // Проверяем датчик 1
    bool sensor = isSensorActive(SENSOR1_PIN);
    static bool prevSensor = false;
    static bool gripExecuted = false;

    if (sensor && !prevSensor) {
        // Появился сигнал
        if (!gripExecuted) {
            // Выполняем силовой схват с удержанием
            executeGrip(GRIP_POWER, true, 90);
            gripExecuted = true;
        } else {
            // Повторный сигнал - выход из удержания (разжатие)
            releaseGrip();
            gripExecuted = false;
        }
    }
    prevSensor = sensor;
}

// ==================== Обработка режимов с двумя датчиками ====================
void processTwoSensors(int mode) {
    // Считываем состояние датчиков
    sensor1Active = isSensorActive(SENSOR1_PIN);
    sensor2Active = isSensorActive(SENSOR2_PIN);

    // Определяем комбинацию
    uint8_t combo = (sensor1Active ? 1 : 0) | (sensor2Active ? 2 : 0);

    // Текущий выбранный схват в зависимости от режима и комбинации
    GripType selectedGrip = GRIP_POWER;
    bool hold = true;
    uint8_t speed = 70;

    if (mode == MODE1) {
        switch (combo) {
            case 1: // только датчик 1
                selectedGrip = GRIP_POWER;
                hold = true;
                speed = 90;
                break;
            case 2: // только датчик 2
                selectedGrip = GRIP_CLOSED_PINCER;
                hold = false;
                speed = 70;
                break;
            case 3: // оба датчика
                selectedGrip = GRIP_OPEN_PINCER;
                hold = true;
                speed = 70;
                break;
            default: // ни один
                selectedGrip = GRIP_POWER; // не используется
                break;
        }
    } else { // MODE2
        switch (combo) {
            case 1:
                selectedGrip = GRIP_POWER;
                hold = true;
                speed = 70;
                break;
            case 2:
                selectedGrip = GRIP_KEYBOARD;
                hold = true;
                speed = 70;
                break;
            case 3:
                selectedGrip = GRIP_CUP_HOLD;
                hold = true;
                speed = 50;
                break;
            default:
                break;
        }
    }

    // Обработка изменения комбинации
    if (combo != (prevSensor1Active?1:0) | (prevSensor2Active?2:0)) {
        // Комбинация изменилась
        if (gripActive && gripHoldActive) {
            // Если был активен схват с удержанием, отпускаем его (разжимаем)
            releaseGrip();
        }
        // Если новая комбинация не пустая, выполняем новый схват
        if (combo != 0) {
            executeGrip(selectedGrip, hold, speed);
        } else {
            // Если все датчики отключены, и не было удержания, то разжимаем (если без удержания)
            if (gripActive && !gripHoldActive) {
                releaseGrip();
            }
        }
    } else {
        // Комбинация не изменилась
        if (combo != 0) {
            // Если схват без удержания и датчики все еще активны, ничего не делаем (пальцы уже в нужном положении)
            // Если схват с удержанием, то он уже выполнен и удерживается
        } else {
            // Датчики отключены
            if (gripActive && !gripHoldActive) {
                releaseGrip();
            }
        }
    }

    prevSensor1Active = sensor1Active;
    prevSensor2Active = sensor2Active;
}

// ==================== Аварийный режим ====================
void processEmergency() {
    // Игнорируем датчики
    // Принудительное раскрытие кисти уже выполнено при входе в режим
    // Светодиод мигает 1 Гц (обрабатывается в updateLED)
    // Выход из аварийного режима по повторному длительному нажатию
    if (emergencyExitPending) {
        // Выходим из аварии, переходим в MODE1 (режим с двумя датчиками)
        currentState = STATE_MODE1;
        ledFlashMode = 1; // светодиод не горит (MODE1)
        emergencyExitPending = false;
        Serial.println("Выход из аварийного режима, переход в MODE1");
        // Сбрасываем флаги кнопки
        buttonLongPressHandled = false;
    }
}

// ==================== Обработка кнопки ====================
void handleButton() {
    static bool lastButtonState = HIGH;
    static unsigned long debounceTime = 0;
    static bool buttonHeld = false;

    bool reading = digitalRead(BUTTON_PIN);
    if (reading != lastButtonState) {
        debounceTime = millis();
    }

    if ((millis() - debounceTime) > BUTTON_DEBOUNCE) {
        if (reading == LOW && !buttonPressed) {
            // Кнопка нажата
            buttonPressed = true;
            buttonPressTime = millis();
            buttonLongPressHandled = false;
            buttonShortPressHandled = false;
        } else if (reading == HIGH && buttonPressed) {
            // Кнопка отпущена
            buttonPressed = false;
            buttonReleaseTime = millis();
            unsigned long pressDuration = buttonReleaseTime - buttonPressTime;

            // Защита от случайного нажатия (<0.3 сек)
            if (pressDuration < SHORT_PRESS_MIN) {
                // Игнорируем
                return;
            }

            // Длительное нажатие (>=3 сек) - аварийный режим
            if (pressDuration >= LONG_PRESS_MIN) {
                // Аварийный режим, если не в аварии
                if (currentState != STATE_EMERGENCY) {
                    enterEmergency();
                } else {
                    // Если уже в аварии, то готовим выход
                    emergencyExitPending = true;
                }
                return;
            }

            // Короткое нажатие (0.3..0.5 сек)
            if (pressDuration >= SHORT_PRESS_MIN && pressDuration <= SHORT_PRESS_MAX) {
                // Обработка одиночного/двойного клика
                unsigned long now = millis();
                if (singleClickPending && (now - lastSingleClickTime) <= DOUBLE_CLICK_INTERVAL) {
                    // Двойной клик
                    doubleClickDetected = true;
                    singleClickPending = false;
                } else {
                    // Первый клик или интервал истёк
                    singleClickPending = true;
                    lastSingleClickTime = now;
                    doubleClickDetected = false;
                }
            }
        }
    }

    lastButtonState = reading;

    // Проверка двойного клика после таймаута
    if (singleClickPending && (millis() - lastSingleClickTime) > DOUBLE_CLICK_INTERVAL) {
        // Одиночный клик
        if (!doubleClickDetected) {
            handleSingleClick();
        }
        singleClickPending = false;
    }

    // Если двойной клик обнаружен
    if (doubleClickDetected) {
        handleDoubleClick();
        doubleClickDetected = false;
        singleClickPending = false;
    }
}

void handleSingleClick() {
    // Переключение между режимами в зависимости от текущего состояния
    if (currentState == STATE_ONE_SENSOR) {
        currentState = STATE_MODE1;
        ledFlashMode = 0; // светодиод не горит
        Serial.println("Переход в MODE1 (одинарный клик)");
    } else if (currentState == STATE_MODE1) {
        // Переключение на MODE2? Но по ТЗ однократное из MODE1? 
        // Скорее всего, однократное из MODE1 переключает на MODE2? 
        // Но в ТЗ: "изменение режимов работы протеза через многофункциональную кнопку"
        // и таблица: Режим 1 - переход при однократном коротком нажатии (из ONE_SENSOR)
        // Режим 2 - при двукратном.
        // После перехода в MODE1, однократное нажатие может переключить обратно в ONE_SENSOR? Или в MODE2?
        // Допустим, что однократное из MODE1 переключает в MODE2, а из MODE2 в MODE1.
        if (currentState == STATE_MODE1) {
            currentState = STATE_MODE2;
            ledFlashMode = 1; // светодиод горит
            Serial.println("Переход в MODE2 (одинарный клик)");
        } else if (currentState == STATE_MODE2) {
            currentState = STATE_MODE1;
            ledFlashMode = 0;
            Serial.println("Переход в MODE1 (одинарный клик)");
        }
    }
}

void handleDoubleClick() {
    // Двойной клик: переход в MODE2 из ONE_SENSOR или MODE1?
    if (currentState == STATE_ONE_SENSOR) {
        currentState = STATE_MODE2;
        ledFlashMode = 1; // светодиод горит
        Serial.println("Переход в MODE2 (двойной клик)");
    } else if (currentState == STATE_MODE1) {
        // Если в MODE1, двойной клик переключает в MODE2?
        currentState = STATE_MODE2;
        ledFlashMode = 1;
        Serial.println("Переход в MODE2 (двойной клик)");
    } else if (currentState == STATE_MODE2) {
        // Из MODE2 двойной клик переключает в MODE1?
        currentState = STATE_MODE1;
        ledFlashMode = 0;
        Serial.println("Переход в MODE1 (двойной клик)");
    }
}

void enterEmergency() {
    // Принудительное раскрытие кисти
    for (int i = 0; i < NUM_FINGERS; i++) {
        setFinger(i, ANGLE_MIN, 100);
    }
    currentState = STATE_EMERGENCY;
    ledFlashMode = 2; // мигание 1 Гц
    emergencyStartTime = millis();
    Serial.println("Аварийный режим активирован!");
}

// ==================== Обработка датчиков ====================
bool isSensorActive(int pin) {
    int val = analogRead(pin);
    return val > SENSOR_THRESHOLD;
}

// ==================== Управление светодиодом ====================
void updateLED() {
    unsigned long now = millis();
    switch (ledFlashMode) {
        case 0: // Выключен
            digitalWrite(LED_PIN, LOW);
            break;
        case 1: // Горит
            digitalWrite(LED_PIN, HIGH);
            break;
        case 2: // Мигание 1 Гц (50% скважность)
            if (now - lastLEDToggleTime >= LED_FLASH_PERIOD / 2) {
                ledState = !ledState;
                digitalWrite(LED_PIN, ledState);
                lastLEDToggleTime = now;
            }
            break;
        case 3: // Два коротких мигания с частотой 1 Гц (специальный паттерн для ONE_SENSOR)
            // Паттерн: два коротких импульса (0.1с вкл, 0.1с выкл, 0.1с вкл, 0.7с выкл) повторяется каждую секунду
            int cycleTime = now % LED_FLASH_PERIOD;
            if (cycleTime < LED_TWO_SHORT_ON) {
                digitalWrite(LED_PIN, HIGH);
            } else if (cycleTime < LED_TWO_SHORT_ON + LED_TWO_SHORT_OFF) {
                digitalWrite(LED_PIN, LOW);
            } else if (cycleTime < 2 * LED_TWO_SHORT_ON + LED_TWO_SHORT_OFF) {
                digitalWrite(LED_PIN, HIGH);
            } else {
                digitalWrite(LED_PIN, LOW);
            }
            break;
    }
}
